    ('fc5e2174-402b-4fcf-9826-77bf9be90957'::uuid, 'card_description', 'Emperor Tiberius ruled the Roman Empire from this clifftop palace on Capri from 27 AD until his death in 37 AD. It was the largest of his twelve villas on the island.', 'Atop Monte Tiberio, Capri, Tiberius ruled mainly from Villa Jovis until his death in 37 AD. Rainwater from its roofs filled a large cistern, and a watch tower sent messages to the mainland.', 'teaser-card-s031:fc5e2174-402b-4fcf-9826-77bf9be90957:card_description', 'teaser-card-s031 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', '978e44b60804fecd6dbd63f68137093eefcf636fd4fbcb8d31d360ae6996a856|91bbae53efe4a05b185943339e5f9f6850811fe97e9814acded75105d53a3eeb|91bbae53efe4a05b185943339e5f9f6850811fe97e9814acded75105d53a3eeb', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Atop Monte Tiberio, Capri, Tiberius ruled mainly from Villa Jovis until his death in 37 AD. Rainwater from its roofs filled a large cistern, and a watch tower sent messages to the mainland."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Villa Jovis stands atop Monte Tiberio [S5]; it is on Capri [S1, S5]; Tiberius ruled mainly from Villa Jovis [S2]; he ruled from there until his death in 37 AD [S2]; rainwater was collected from the villa''s roofs [S7]; a large cistern was filled with the collected rainwater [S7]; a watch tower was used to send messages to the mainland [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-089 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Villa Jovis is a Roman palace (villa) on Capri, Italy, built by Emperor Tiberius [SUPPORTED: https://en.wikipedia.org/wiki/Villa_Jovis]; Villa Jovis stands atop Monte Tiberio on Capri [SUPPORTED: https://en.wikipedia.org/wiki/Villa_Jovis]; Tiberius ruled mainly from Villa Jovis [SUPPORTED: https://en.wikipedia.org/wiki/Villa_Jovis]; Tiberius ruled from Villa Jovis until his death in 37 AD [SUPPORTED: https://en.wikipedia.org/wiki/Villa_Jovis]; Rainwater from the villa''s roofs was collected [SUPPORTED: https://en.wikipedia.org/wiki/Villa_Jovis]; The villa had a large cistern that supplied the palace with water [SUPPORTED: https://en.wikipedia.org/wiki/Villa_Jovis]; A watch tower stood at the villa [SUPPORTED: https://en.wikipedia.org/wiki/Villa_Jovis]; The watch tower was used to send messages to the mainland [SUPPORTED: https://en.wikipedia.org/wiki/Villa_Jovis]"}]'::jsonb),
    ('fd94d469-92a0-4796-a7a8-64f925f01773'::uuid, 'card_description', 'A Neolithic axe quarry producing porcellanite tools traded across the British Isles. Axes from this mountain have surfaced from the Outer Hebrides to the south coast.', 'At the foot of Tievebulliagh in the Glens of Antrim lay a Neolithic axe quarry. Porcellanite axes roughed out here were finished at the sea shore and found across the British Isles.', 'teaser-card-s031:fd94d469-92a0-4796-a7a8-64f925f01773:card_description', 'teaser-card-s031 (teaser-card): teaser card, 181 characters, checked PASS, web-verified VERIFIED', '0ec1b1f91cd556d32e9484da223964443455acb773d639f1ba086feb395a703e|da61b90c2d99bba3b0f42fe701eaaf2997aadcb454e516f4543423d8504691be|da61b90c2d99bba3b0f42fe701eaaf2997aadcb454e516f4543423d8504691be', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "At the foot of Tievebulliagh in the Glens of Antrim lay a Neolithic axe quarry. Porcellanite axes roughed out here were finished at the sea shore and found across the British Isles."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Tievebulliagh is in the Glens of Antrim [S1]; a Neolithic axe quarry lay at the foot of Tievebulliagh [S2]; the axes were made of porcellanite [S3]; the axes were roughed out at this site [S5]; the axes were finished at the sea shore [S5]; axes from this quarry were found across the British Isles [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-089 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Tievebulliagh is a mountain in the Glens of Antrim (Northern Ireland) [SUPPORTED: https://en.wikipedia.org/wiki/Tievebulliagh]; At the foot of Tievebulliagh there was an axe quarry [SUPPORTED: https://en.wikipedia.org/wiki/Tievebulliagh]; The quarry dates to the Neolithic [SUPPORTED: https://en.wikipedia.org/wiki/Tievebulliagh]; The axes were made of porcellanite [SUPPORTED: https://en.wikipedia.org/wiki/Tievebulliagh]; The axes were roughed out at the quarry on the hill [SUPPORTED: https://en.wikipedia.org/wiki/Tievebulliagh]; The axes were finished at the sea shore [SUPPORTED: https://en.wikipedia.org/wiki/Tievebulliagh]; Porcellanite axes from this quarry were found across the British Isles [SUPPORTED: https://en.wikipedia.org/wiki/Tievebulliagh]"}]'::jsonb),
    ('fd9e31aa-e71d-4cf1-81ff-4104b7df8465'::uuid, 'card_description', 'At the rim of the Vale of Pewsey, this causewayed enclosure from around 3700 BC has ditches broken by characteristic gaps. Whether settlement, meeting place, or ritual site remains debated.', 'On the northern rim of the Vale of Pewsey, Knap Hill holds the first causewayed enclosure to be excavated and identified, its ditches broken by gaps, and a Romano-British settlement.', 'teaser-card-s031:fd9e31aa-e71d-4cf1-81ff-4104b7df8465:card_description', 'teaser-card-s031 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', '0c48ee44e45518944e73226bf19810388afc167b51d24e8a99c5815eaad324f4|ab2db5ac3709da7a9ec1241a004178c1ab736f340fdd0e0290cc9c1779737b11|ab2db5ac3709da7a9ec1241a004178c1ab736f340fdd0e0290cc9c1779737b11', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-rewrite-v-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On the northern rim of the Vale of Pewsey, Knap Hill holds the first causewayed enclosure to be excavated and identified, its ditches broken by gaps, and a Romano-British settlement."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-v-003 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Knap Hill lies on the northern rim of the Vale of Pewsey [S1]; Knap Hill has a causewayed enclosure [S2]; it is the first causewayed enclosure to be excavated and identified [S3]; the enclosure''s ditches are broken by gaps [S2]; the hill holds a Romano-British settlement [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify2-006 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Knap Hill is a causewayed enclosure site in Wiltshire [SUPPORTED: https://en.wikipedia.org/wiki/Knap_Hill]; Knap Hill lies on the northern rim of the Vale of Pewsey and has a causewayed enclosure at its top [SUPPORTED: https://en.wikipedia.org/wiki/Knap_Hill]; It is the first causewayed enclosure to be excavated [SUPPORTED: https://en.wikipedia.org/wiki/Knap_Hill]; It is the first causewayed enclosure to be identified [SUPPORTED: https://en.wikipedia.org/wiki/Knap_Hill]; The enclosure''s ditches are interrupted by gaps [SUPPORTED: https://en.wikipedia.org/wiki/Knap_Hill]; The hilltop has a Romano-British settlement [SUPPORTED: https://en.wikipedia.org/wiki/Knap_Hill]"}]'::jsonb),
    ('fdafef27-24a2-4939-b2b0-7f3852676e82'::uuid, 'card_description', 'A 3rd-century BC Celtic city that later became Roman Singidunum — the foundation beneath modern Belgrade. The Scordisci tribe named it.', 'On the hilltop where the Danube meets the Sava, the Celtic Scordisci are credited with founding Singidunum, first mentioned in 279 BCE as already fortified. Emperor Jovian was born here.', 'teaser-card-s031:fdafef27-24a2-4939-b2b0-7f3852676e82:card_description', 'teaser-card-s031 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', '2a984df8f77a467351ee71ca52c97f695db46f71579769bff2c2a00d2015d9d8|71f66a27ade2f769cebe2bc0a366b6689fe67f3188c66d61304d12d3ed1dfd16|71f66a27ade2f769cebe2bc0a366b6689fe67f3188c66d61304d12d3ed1dfd16', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On the hilltop where the Danube meets the Sava, the Celtic Scordisci are credited with founding Singidunum, first mentioned in 279 BCE as already fortified. Emperor Jovian was born here."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Singidunum stands on a hilltop where the Danube meets the Sava [S5]; the Scordisci are a Celtic tribe [S5]; the Scordisci are credited with founding Singidunum [S6]; Singidunum was first mentioned in 279 BCE [S6]; it was already fortified when first mentioned [S6]; Emperor Jovian was born at Singidunum [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-089 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Singidunum was an ancient city (a fortified settlement) that later became Belgrade, Serbia [SUPPORTED: https://en.wikipedia.org/wiki/Singidunum]; Singidunum lay on a hilltop where the Danube meets the Sava [SUPPORTED: https://en.wikipedia.org/wiki/Singidunum]; The Scordisci were a Celtic tribe [SUPPORTED: https://en.wikipedia.org/wiki/Singidunum]; The Scordisci are credited with founding Singidunum [SUPPORTED: https://en.wikipedia.org/wiki/Singidunum]; Singidunum was first mentioned in 279 BCE as an already fortified settlement [SUPPORTED: https://en.wikipedia.org/wiki/Singidunum]; Emperor Jovian was born in Singidunum [SUPPORTED: https://en.wikipedia.org/wiki/Singidunum]"}]'::jsonb),
    ('fe7d7ee7-ca93-4cf5-93d8-0cc80564ccd8'::uuid, 'card_description', 'The Romans founded the settlement and named it Calcaria from the Latin word for lime kilns.', 'The Romans named Calcaria for the Latin word for lime kilns. At a river crossing on the road from Danum to Eburacum, it may have begun as an Imperial staging post; its nature is uncertain.', 'teaser-card-s031:fe7d7ee7-ca93-4cf5-93d8-0cc80564ccd8:card_description', 'teaser-card-s031 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', 'a45361eae5854b42eed1c811a6e7d3eb713824c9a19c344d9d63416299121393|e1fc229a9835b5f60b77f8e9689025f8b7e251bc12292ce87f66131ad7a208de|e1fc229a9835b5f60b77f8e9689025f8b7e251bc12292ce87f66131ad7a208de', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Romans named Calcaria for the Latin word for lime kilns. At a river crossing on the road from Danum to Eburacum, it may have begun as an Imperial staging post; its nature is uncertain."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the Romans named Calcaria [S1]; the name comes from the Latin word for lime kilns [S1]; it lies at a river crossing [S3]; it lies on the road from Danum to Eburacum [S3]; it may have begun as an Imperial staging post [S3]; the nature of the settlement is uncertain [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-089 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Calcaria was a Roman settlement (a town in Roman Britain, today Tadcaster, England) [SUPPORTED: https://en.wikipedia.org/wiki/Calcaria]; The Romans founded the settlement and named it Calcaria [SUPPORTED: https://en.wikipedia.org/wiki/Calcaria]; The name Calcaria comes from the Latin word for lime kilns [SUPPORTED: https://en.wikipedia.org/wiki/Calcaria]; Calcaria lay at a river crossing on the road from Danum to Eburacum [SUPPORTED: https://en.wikipedia.org/wiki/Calcaria]; Calcaria may have begun as an Imperial staging post [SUPPORTED: https://en.wikipedia.org/wiki/Calcaria]; The nature of the settlement is uncertain [SUPPORTED: https://en.wikipedia.org/wiki/Calcaria]"}]'::jsonb),
    ('fea0865c-9b28-4d88-9f66-36e61ed0f0e2'::uuid, 'card_description', 'The bridge was constructed at the end of the 1st century or beginning of the 2nd century, by engineers under the emperor Trajan.', 'Over the Tâmega River in Chaves, Trajan''s Bridge was built by engineers under Trajan. In the 16th century Duarte d''Armas drew it with 14 arches and watermills on the northern bank.', 'teaser-card-s031:fea0865c-9b28-4d88-9f66-36e61ed0f0e2:card_description', 'teaser-card-s031 (teaser-card): teaser card, 180 characters, checked PASS, web-verified VERIFIED', 'adcd7c65d1e163f6ce13fa68919b63ea47e3882b91d8a23e67be33d38c4750c9|f6828fcd1201cf1c8e4f0cd8ef24225391213133e7f66ba2e5cf8fc66ef87674|f6828fcd1201cf1c8e4f0cd8ef24225391213133e7f66ba2e5cf8fc66ef87674', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Over the Tâmega River in Chaves, Trajan''s Bridge was built by engineers under Trajan. In the 16th century Duarte d''Armas drew it with 14 arches and watermills on the northern bank."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Trajan''s Bridge spans the Tâmega River [S4]; it is in Chaves [S1]; it was built by engineers under Trajan [S2]; in the 16th century Duarte d''Armas depicted it [S3]; the depiction shows 14 arches [S3]; the depiction shows watermills on the northern bank [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-090 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Trajan''s Bridge is a Roman bridge in Chaves, Portugal [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Bridge_of_Chaves]; The bridge crosses the Tâmega River [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Bridge_of_Chaves]; It was built by engineers [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Bridge_of_Chaves]; The engineers worked under (the emperor) Trajan [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Bridge_of_Chaves]; Duarte d''Armas depicted (drew) the bridge in the 16th century [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Bridge_of_Chaves]; Duarte d''Armas''s drawing shows the bridge with 14 arches [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Bridge_of_Chaves]; Duarte d''Armas''s drawing shows watermills on the northern bank [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Bridge_of_Chaves]"}]'::jsonb),
    ('ff29e0ab-00e7-471c-974f-639b900ea612'::uuid, 'card_description', 'A 167-monolith stone circle surrounding a 58-meter tumulus. One stone called "El Uted" stands over 5 meters tall — towering above the rest.', '167 monoliths ring a tumulus at Cromlech de Mzoura, El Uted among them at more than 5 m. Dated to the 4th or 3rd century BC, it probably hints at the dawn of the Kingdom of Mauretania.', 'teaser-card-s031:ff29e0ab-00e7-471c-974f-639b900ea612:card_description', 'teaser-card-s031 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', '8928f48d2557bf5bdee42125aa69d84f81248f949235519d641670dac6f9ffbc|f70888da36876a8812a3164d2a4f183e6fd7daf86f4685053b67fdd6507516bb|f70888da36876a8812a3164d2a4f183e6fd7daf86f4685053b67fdd6507516bb', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "167 monoliths ring a tumulus at Cromlech de Mzoura, El Uted among them at more than 5 m. Dated to the 4th or 3rd century BC, it probably hints at the dawn of the Kingdom of Mauretania."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "167 monoliths stand at the site [S2]; the monoliths surround (ring) a tumulus [S2]; El Uted is one of the monoliths [S3]; El Uted measures more than 5 m [S3]; the site is dated to the 4th or 3rd century BC [S4]; the site probably hints at the beginnings of the Kingdom of Mauretania [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-090 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Cromlech de Mzoura (Mzoura/Msoura) is a stone circle, an archaeological site in Morocco [SUPPORTED: https://en.wikipedia.org/wiki/Msoura]; The site has a tumulus ringed by monoliths [SUPPORTED: https://en.wikipedia.org/wiki/Msoura]; 167 monoliths ring the tumulus [SUPPORTED: https://en.wikipedia.org/wiki/Msoura]; El Uted is one of the monoliths of the ring [SUPPORTED: https://en.wikipedia.org/wiki/Msoura]; El Uted measures more than 5 m [SUPPORTED: https://en.wikipedia.org/wiki/Msoura]; The site is dated to the 4th or 3rd century BC [SUPPORTED: https://en.wikipedia.org/wiki/Msoura]; The site probably hints at the beginnings of the Kingdom of Mauretania [SUPPORTED: https://en.wikipedia.org/wiki/Msoura]"}]'::jsonb),
    ('ff38d0f1-cb2f-4a71-ad13-e925af8488a7'::uuid, 'card_description', 'Three 1.7-metre support stones in a U-shape hold a partly slipped capstone on Mulfra Hill, Cornwall. From the hilltop the sea is visible over the surrounding landscape — a prominent Neolithic marker.', 'Atop Mulfra Hill in Cornwall stands Mulfra Quoit, a Neolithic dolmen whose capstone of 5 tonnes has slipped down. Excavations in 1872 in its centre yielded only charred wood.', 'teaser-card-s031:ff38d0f1-cb2f-4a71-ad13-e925af8488a7:card_description', 'teaser-card-s031 (teaser-card): teaser card, 174 characters, checked PASS, web-verified VERIFIED', '0fd8ac29d1b5120501d1e10c781dc9772442fe8ad7f545b7b400c8c6071d1565|491cfde0b6936c8ed4fb935b6360d9bf76324b73a8eb914e5881fb51f16999c3|491cfde0b6936c8ed4fb935b6360d9bf76324b73a8eb914e5881fb51f16999c3', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Atop Mulfra Hill in Cornwall stands Mulfra Quoit, a Neolithic dolmen whose capstone of 5 tonnes has slipped down. Excavations in 1872 in its centre yielded only charred wood."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Mulfra Quoit stands atop Mulfra Hill [S2, S3]; it is in Cornwall [S1]; it is a Neolithic dolmen [S1]; its capstone weighs 5 tonnes [S5]; the capstone has slipped down [S5]; excavations took place in 1872 [S7]; the excavations were in the centre of the dolmen [S7]; the excavations yielded only charred wood [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-090 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Mulfra Quoit is a dolmen (quoit) [SUPPORTED: https://en.wikipedia.org/wiki/Mulfra_Quoit]; Mulfra Quoit is Neolithic [SUPPORTED: https://en.wikipedia.org/wiki/Mulfra_Quoit]; It is in Cornwall [SUPPORTED: https://en.wikipedia.org/wiki/Mulfra_Quoit]; It stands atop Mulfra Hill [SUPPORTED: https://en.wikipedia.org/wiki/Mulfra_Quoit]; Its capstone has slipped down [SUPPORTED: https://en.wikipedia.org/wiki/Mulfra_Quoit]; The capstone weighs 5 tonnes [SUPPORTED: https://en.wikipedia.org/wiki/Mulfra_Quoit]; Excavations took place in 1872 [SUPPORTED: https://en.wikipedia.org/wiki/Mulfra_Quoit]; The 1872 excavations were in the centre of the dolmen [SUPPORTED: https://en.wikipedia.org/wiki/Mulfra_Quoit]; The excavations yielded only charred wood [SUPPORTED: https://en.wikipedia.org/wiki/Mulfra_Quoit]"}]'::jsonb),
    ('ff4dc88e-bebe-4b88-90d3-6697bffc9107'::uuid, 'card_description', 'An Inca-period site in the remote Cusco highlands, perched on the banks of the Luq''umayu river. Its purpose and builders remain poorly documented.', 'On the right bank of the Luq''umayu in La Convención Province, Cusco, lies Huamanmarca, an archaeological site whose name possibly comes from the Quechua words for falcon and village.', 'teaser-card-s031:ff4dc88e-bebe-4b88-90d3-6697bffc9107:card_description', 'teaser-card-s031 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', 'c370453877abcda0e1a609b4a2e6b91d220afd215a43c6d91d53b2d220dec609|4e917a8d11e97f253d2fd10e30ab2d28d6c070a1d936cee8460d124455981f50|4e917a8d11e97f253d2fd10e30ab2d28d6c070a1d936cee8460d124455981f50', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On the right bank of the Luq''umayu in La Convención Province, Cusco, lies Huamanmarca, an archaeological site whose name possibly comes from the Quechua words for falcon and village."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Huamanmarca lies on the right bank of the Luq''umayu [S2]; it is in La Convención Province [S2]; it is in Cusco (region) [S1]; it is an archaeological site [S1]; the name possibly comes from the Quechua words for falcon and village [S1]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-090 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Huamanmarca is an archaeological site [SUPPORTED: https://en.wikipedia.org/wiki/Huamanmarca,_La_Convenci%C3%B3n]; It is in the Cusco region of Peru [SUPPORTED: https://en.wikipedia.org/wiki/Huamanmarca,_La_Convenci%C3%B3n]; It is in La Convención Province [SUPPORTED: https://en.wikipedia.org/wiki/Huamanmarca,_La_Convenci%C3%B3n]; It lies on the right bank of the Luq''umayu [SUPPORTED: https://en.wikipedia.org/wiki/Huamanmarca,_La_Convenci%C3%B3n]; The name possibly comes from the Quechua words waman (falcon) and marka (village) [SUPPORTED: https://en.wikipedia.org/wiki/Huamanmarca,_La_Convenci%C3%B3n]"}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 50;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a card_stats row of a curated site that still exists
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN card_stats t ON t.site_id = p.site_id
      LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE t.site_id IS NULL OR u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'teaser card: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _teaser_card_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'card_description' THEN p.new_value::character varying IS NOT DISTINCT FROM p.old_value::character varying OR length(p.new_value) > 200
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.old_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 5: every planned row still holds the input its value was derived from
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id, premise FROM _teaser_card_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE (coalesce(u.raw_data -> '_card_provenance' ->> 'text_sha256', '') || '|' || coalesce(u.raw_data -> '_card_provenance' ->> 'desc_sha256', '') || '|' || encode(sha256(convert_to(coalesce(u.description, ''), 'UTF8')), 'hex')) IS DISTINCT FROM p.premise;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the premise the plan derived its value from', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _teaser_card_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'card_stats', r.column_name, 'site_id', r.site_id::text,
            r.old_value, r.new_value,
            'WB/teaser-card', 'wb-teaser-card-s031', r.change_key, 'opus-checked', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'teaser card: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.new_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'card_stats'
       AND l.column_name = p.column_name
       AND l.run_stamp = 'wb-teaser-card-s031'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = 'wb-teaser-card-s031'
       AND (l.table_name <> 'card_stats' OR l.column_name NOT IN ('card_description'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: this run stamp journalled % row(s) outside card_stats.(card_description)', bad;
    END IF;

    RAISE NOTICE 'teaser card: % of % planned cell(s) changed and journalled over 50 curated site(s)',
        moved, expected;
END $$;

COMMIT;

-- Post-commit read: the numbers the report quotes, from the database, not from the plan.
SELECT 'journal rows for this run stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = 'wb-teaser-card-s031'
UNION ALL
SELECT 'journal rows for this test id', count(*)::text
  FROM remediation_change_log WHERE test_id = 'WB/teaser-card'
UNION ALL
SELECT 'planned rows now holding the new value', count(*)::text
  FROM remediation_change_log l
 WHERE l.run_stamp = 'wb-teaser-card-s031' AND l.table_name = 'card_stats'
   AND l.column_name IN ('card_description')
   AND EXISTS (SELECT 1 FROM card_stats t
                WHERE t.site_id::text = l.row_pk AND CASE l.column_name
                WHEN 'card_description' THEN t.card_description IS NOT DISTINCT FROM l.new_value::character varying
                ELSE false END)
UNION ALL
SELECT 'curated sites whose teaser provenance does not hash their live card', count(*)::text
  FROM unified_sites
 WHERE source_id = 'ancient_nerds' AND raw_data ? '_card_provenance' AND NOT EXISTS (SELECT 1 FROM card_stats cs WHERE cs.site_id = unified_sites.id AND encode(sha256(convert_to(cs.card_description, 'UTF8')), 'hex') = unified_sites.raw_data -> '_card_provenance' ->> 'text_sha256')
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds';
